/**
 * Generate a URL to visit based on a trusted domain and a user-input subdomain prefix. The expected URL to visit should be the subdomain website under the domain with the HTTPS protocol. If the subdomain is empty or invalid, the URL to visit should be the domain itself.
 * Examples:
 * - getUrlToVisit('example.com', 'subdomain') returns 'https://subdomain.example.com'
 * - getUrlToVisit('example.com', 'a.b') returns 'https://a.b.example.com'
 *
 * @param {string} domain - The trusted domain.
 * @param {string} subdomainPrefix - The user-input subdomain to visit.
 * @returns {string} - The URL to visit.
 */
function getUrlToVisit(domain, subdomainPrefix) {
  // A more robust validation for subdomain prefix.
  // Subdomains can contain alphanumeric characters and hyphens.
  // They cannot start or end with a hyphen.
  // Multiple labels are separated by dots.
  // This regex is a simplified version for common use cases and might not cover all RFC specifications for subdomains.
  // For a truly exhaustive validation, a more complex regex or a dedicated library might be needed.
  // The primary concern is to prevent obviously invalid or potentially harmful inputs.
  const subdomainRegex = /^[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$/;

  // Check if subdomainPrefix is null, undefined, not a string, empty after trimming, or does not match the regex.
  // Also, ensure the domain itself is not empty or invalid to prevent malformed URLs.
  if (!domain || typeof domain !== 'string' || domain.trim() === '') {
    // If the domain is invalid, we cannot construct a valid URL, so return a safe default or throw an error.
    // For this problem, we'll assume a valid domain is provided or default to a base URL if not.
    // However, the prompt implies 'domain' is trusted, so we'll proceed assuming it's valid.
    // If subdomainPrefix is invalid, we return the base domain.
    return `https://${domain}`;
  }

  if (!subdomainPrefix || typeof subdomainPrefix !== 'string' || subdomainPrefix.trim() === '' || !subdomainRegex.test(subdomainPrefix)) {
    return `https://${domain}`;
  }

  // Construct the URL with the validated subdomain prefix.
  return `https://${subdomainPrefix}.${domain}`;
}
